NDL_st.name='NDL'; 
NDL_st.lat=28.62;
NDL_st.lon=77.21;
NDL_st.alt=0000;
NDL_st.env='Con';
NDL_st.footp='U';
%%
% data imported via the import tool from matlab
 NDL_rd_h = importfile("C:\github_trend\raw_data\Aethalometer_India\Aethalometer\NDL_2016-2026_Hour.csv", [2, Inf]);
NDL_rd_h.Properties.DimensionNames{1}='Time';
NDL_rd_h.Properties.VariableNames{2}='Ba1_A';
NDL_rd_h.Properties.VariableNames{3}='Ba2_A';
NDL_rd_h.Properties.VariableNames{4}='Ba3_A';
NDL_rd_h.Properties.VariableNames{5}='Ba4_A';
NDL_rd_h.Properties.VariableNames{6}='Ba5_A';
NDL_rd_h.Properties.VariableNames{7}='Ba6_A';
NDL_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(NDL_rd_h);
%%
NDL_rd=retime(NDL_rd_h,'daily',@nanmedian);
%%
datevec(NDL_rd.Time(1)) % begin in 2016,  %[output:4cf3de4c]
datevec(NDL_rd.Time(end)) % end in 2024 March too short %[output:4e38f455]
plotFigControl(NDL_rd,NDL_st.name);  %[output:07e0230a] %[output:3f340f3b] %[output:644a231b] %[output:1f160195] %[output:172719f7] %[output:9effd36a] %[output:6d627d2f] %[output:848f42e2]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
NDL_cal=compute_exp_D(NDL_rd,names_abs,lambdaAE7); %[output:22153952] %[output:1e8e59e9] %[output:615344ca] %[output:7b516299] %[output:620ca852] %[output:96bb6051] %[output:8404ea1b] %[output:9973c6e2] %[output:06833335] %[output:2a2e5450] %[output:7da9409d] %[output:5bc7afee] %[output:4518dbad] %[output:03ba23a4] %[output:921d424c] %[output:9cd5ac75] %[output:30882dc1] %[output:3d21bd00] %[output:34b3886e] %[output:451c1d72] %[output:05af39e2] %[output:9a0d0e67] %[output:3f0f95d6] %[output:79ea025d] %[output:3dd6fbab] %[output:353c60a7] %[output:5320f4dd] %[output:5f591d75] %[output:62bc6f6c] %[output:1d31f6f7] %[output:582a9ac9] %[output:95caf4af] %[output:06136073] %[output:2b57e0f9] %[output:672719a3] %[output:6e8aa30c] %[output:6e557d9f] %[output:8a7f9d3c] %[output:63bb117a] %[output:2658655b] %[output:5580a6db] %[output:3d0020c5] %[output:34e5d096] %[output:0627ca99] %[output:5288cdae] %[output:64bdbaee] %[output:1b3910c4] %[output:1b0cc313] %[output:2f09e396]
plotFigControl_cal(NDL_cal,NDL_st.name); %[output:34edcaf0] %[output:7effa4a9] %[output:9e492684]
%%
%HOMOGENEITY

break_NDL_abs_BP=change_point_analysis_Def(NDL_rd,names_abs,0.05,'NDL','Absorption'); %[output:9a5e084b] %[output:0f34fdf8] %[output:36a3fe3e] %[output:343be5f1] %[output:912983b3] %[output:53958bab]
T_NDL_abs_BP=make_table_breakpoints_def(break_NDL_abs_BP);

names_expA={'expA_fit'} %[output:83958236]
break_NDL_expA_BP=change_point_analysis_Def(NDL_cal,names_expA,0.05,'NDL','Absorption exponent'); %[output:760288a2] %[output:3d588717] %[output:90ed731a] %[output:5c7dd129]
T_NDL_expA_BP=make_table_breakpoints_def(break_NDL_expA_BP); %[output:9eaccd1c] %[output:5effe6aa] %[output:98237997] %[output:9a34464f] %[output:2a4e5d4a] %[output:55b82947] %[output:586f090f] %[output:461fb1d1] %[output:2a858559] %[output:65153805] %[output:5b25229a] %[output:07df814d] %[output:78d195b3] %[output:5b1b0f2b] %[output:385dec73] %[output:0cbc1cdc] %[output:05751137] %[output:0bc2e582] %[output:82a61766] %[output:5e7e7245] %[output:2bab181b] %[output:42b445d0] %[output:9ef76e59] %[output:61a69728]

%%
NDL_tr=outerjoin(NDL_rd, NDL_cal);
NDL_tr.y=year(NDL_tr.Time);
% begin at the beginning of a year: 2016 
%end: 2025
P=timerange('2016-01-01','2024-01-01');
NDL_tr=NDL_tr(P,:);

