[NDL_result_MK,NDL_result_LMSlog,NDL_result_LMSlin]=all_trend_STN(NDL_tr,NDL_st); %[output:5f013c44] %[output:2b646444] %[output:574af425] %[output:92990dee] %[output:924d91cf] %[output:93476eac] %[output:6d831fad] %[output:881e7bd5]

